package science.transductive.nudge.core;
import com.sun.net.httpserver.*;import science.transductive.nudge.WorkerClient;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
public final class TransportTests {static int n=0;static void ok(boolean v,String name){n++;if(!v)throw new AssertionError(name);System.out.println("PASS "+name);}static byte[] readAll(InputStream in)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();byte[]buf=new byte[4096];for(int k;(k=in.read(buf))!=-1;)b.write(buf,0,k);return b.toByteArray();}static void reply(HttpExchange x,int code,String body)throws IOException{byte[]b=body.getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(code,b.length);OutputStream o=x.getResponseBody();try{o.write(b);}finally{o.close();}}
public static void main(String[]args)throws Exception{long now=System.currentTimeMillis();final String interaction="{\"protocol\":\"NUDGE_PROTOCOL/1\",\"interactionId\":\"transport-1\",\"issuedAtMs\":"+(now-1000)+",\"triggerAtMs\":"+now+",\"expiresAtMs\":"+(now+60000)+",\"title\":\"Test\",\"readyGate\":false,\"prompt\":\"Pick\",\"attention\":\"HEADS_UP\",\"capture\":\"CHOICE\",\"choices\":[{\"id\":\"yes\",\"label\":\"YES\"}],\"countdownMs\":0,\"requiresExactTiming\":false,\"requestFullScreen\":false}";final List<String>eventKeys=new CopyOnWriteArrayList<String>();final List<Integer>audioSizes=new CopyOnWriteArrayList<Integer>();final List<String>queries=new CopyOnWriteArrayList<String>();HttpServer s=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);s.createContext("/v1/next",new HttpHandler(){public void handle(HttpExchange x)throws IOException{queries.add(x.getRequestURI().getRawQuery());reply(x,200,interaction);}});s.createContext("/v1/events",new HttpHandler(){public void handle(HttpExchange x)throws IOException{eventKeys.add(x.getRequestHeaders().getFirst("Idempotency-Key"));readAll(x.getRequestBody());reply(x,200,"{\"ok\":true}");}});s.createContext("/v1/audio",new HttpHandler(){public void handle(HttpExchange x)throws IOException{eventKeys.add(x.getRequestHeaders().getFirst("Idempotency-Key"));audioSizes.add(readAll(x.getRequestBody()).length);reply(x,200,"{\"audioRef\":\"audio/test-1\"}");}});s.start();try{WorkerClient c=new WorkerClient("http://127.0.0.1:"+s.getAddress().getPort(),"secret");String got=c.next("device x");Protocol.parseInteraction(got);ok(queries.get(0).contains("waitSeconds=45")&&queries.get(0).contains("device=device+x"),"long_poll_query");Models.InteractionSpec spec=Protocol.parseInteraction(got);Models.ResponseEvent e=Protocol.choiceEvent(spec,"ev-choice","yes",System.currentTimeMillis());c.postEvent(Protocol.stringifyResponse(e),"ev-choice");ok(eventKeys.contains("ev-choice"),"event_idempotency_header");Path f=Files.createTempFile("nudge-audio",".m4a");Files.write(f,new byte[]{1,2,3,4,5,6});String ref=c.uploadAudio(f.toFile(),spec.interactionId(),"ev-audio");ok("audio/test-1".equals(ref)&&audioSizes.get(0)==6,"audio_upload_and_ref");Files.deleteIfExists(f);}finally{s.stop(0);}System.out.println("TRANSPORT_TESTS_PASS="+n);}}
